package com.example

/**
 * 11 ශ්‍රේණිය ඉතිහාසය - කාණ්ඩ 17 සිට 20 දක්වා (80 unique cards).
 * 100% curriculum-aligned with official Sri Lankan O/L Grade 11 History Syllabus.
 */
object FlashcardBankHistoryGrade11SetsPart3 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      17 -> set17FrenchRevolutionAndLiberty[(c - 1) % 20]
      18 -> set18WorldHeritageSitesAndPreservation[(c - 1) % 20]
      19 -> set19ConstitutionalEvolutionSriLanka[(c - 1) % 20]
      20 -> set20Grade11MasteryGuide[(c - 1) % 20]
      else -> null
    }
  }

  // --- SET 17: ප්‍රංශ විප්ලවය හා නිදහස් සංකල්ප (Grade 11) ---
